// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol"; // Updated import
import "@openzeppelin/contracts/access/Ownable.sol";

interface IUniswapV3Pool {
    function slot0()
        external
        view
        returns (
            uint160 sqrtPriceX96,
            int24 tick,
            uint16 observationIndex,
            uint16 observationCardinality,
            uint16 observationCardinalityNext,
            uint8 feeProtocol,
            bool unlocked
        );
}

contract UniswapPriceOracle is Ownable {
    address public constant ETH_USDC_POOL = 0x88e6A0c2dDD26FEEb64F039a2c41296FcB3f5640;
    address public constant USDC_TOKEN = 0xA0b86991c6218b36c1d19D4a2e9Eb0cE3606eB48;

    constructor() Ownable(msg.sender) {} // Fixed: Pass initial owner

    function getETHPrice() public view returns (uint256) {
        IUniswapV3Pool pool = IUniswapV3Pool(ETH_USDC_POOL);
        (uint160 sqrtPriceX96, , , , , , ) = pool.slot0();

        uint256 priceX96 = uint256(sqrtPriceX96) * uint256(sqrtPriceX96);
        uint256 price = (priceX96 * 1e18) / (2 ** 192);

        // Use IERC20Metadata for decimals()
        uint256 usdcDecimals = 10 ** IERC20Metadata(USDC_TOKEN).decimals();
        return (price * usdcDecimals) / 1e18;
    }
}

